def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: the number of nanoseconds since the Unix epoch
    :param tz: timezone to apply to the time, defaults to None (UTC)
    :return: Time object
    """
    if nanoseconds is None:
        raise ValueError("nanoseconds cannot be None")

    if not isinstance(nanoseconds, int):
        raise TypeError("nanoseconds must be an integer")

    if tz is not None and not isinstance(tz, timezone):
        raise TypeError("tz must be a timezone object or None")

    # Convert nanoseconds to seconds and create a datetime object
    delta = timedelta(seconds=nanoseconds // 1_000_000_000)
    dt = datetime(1970, 1, 1) + delta

    if tz is not None:
        dt = dt.replace(tzinfo=tz)

    # Return the time part of the datetime object
    return dt.time()

