from datetime import datetime, timezone, timedelta

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: int, the nanoseconds to hydrate
    :param tz: str or timezone, the timezone to use for the hydration
    :return: datetime
    """
    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    seconds = nanoseconds // 1_000_000_000
    nanoseconds = nanoseconds % 1_000_000_000

    if tz is None:
        return datetime.utcfromtimestamp(seconds) + timedelta(nanoseconds=nanoseconds)
    elif isinstance(tz, str):
        tz = timezone.utc if tz.lower() == 'utc' else timezone(timedelta(hours=int(tz)))
    elif not isinstance(tz, timezone):
        raise ValueError("tz must be a string or a timezone object")

    return datetime.fromtimestamp(seconds, tz) + timedelta(nanoseconds=nanoseconds)

