            raise ValueError(f"Expected {len(fields)} arguments, got {len(args)}")
        if any(arg not in srid_map for arg in kwargs.values()):
            raise ValueError("Invalid SRID in kwargs")
        return PointBase(*args, **kwargs)

    Point.__name__ = name
    Point srid_map = srid_map

