from threading import Lock

def hashkey(func, *args, **kwargs):
    return hash((func.__name__, args, tuple(sorted(kwargs.items()))))

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    :param cache: A dictionary or similar object with a hashable key type.
    :param key: A function that takes the method, its positional and keyword
               arguments, and returns a hashable cache key. The default key
               function uses the method name, args, and sorted items of kwargs.
    :param lock: A threading.Lock object to use for synchronization. If not
                 provided, no synchronization will be performed.
    """
    def decorator(method):
        @wraps(method)
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                k = key(method, *args, **kwargs)
                if k not in cache:
                    cache[k] = method(self, *args, **kwargs)
                return cache[k]
            finally:
                if lock is not None:
                    lock.release()
        return wrapper
    return decorator

import traceback

class ExceptionFormatter:
    @classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        try:
            stack_trace = traceback.extract_tb(e.__traceback__)
            formatted_trace = []
            for i, tb in enumerate(stack_trace):
                if i >= max_level:
                    break
                file_path = tb.filename
                line_number = tb.lineno
                function_name = tb.name
                formatted_trace.append(f"File: {file_path}, Line: {line_number}, Function: {function_name}")

                file_lines = []
                with open(file_path, 'r') as file:
                    for j, line in enumerate(file):
                        if j >= max_path_level and j < line_number:
                            continue
                        file_lines.append(line.strip())
                formatted_trace.extend(file_lines)

                formatted_trace.append('-' * 80)

            return '\n'.join(formatted_trace)
        except Exception as e:
            return f"Error processing exception: {e}"

