    def is_dependent(a, b, dependencies):
        if a == b:
            return False
        if b not in dependencies:
            return False
        if a in dependencies[b]:
            return True
        for c in dependencies[b]:
            if is_dependent(a, c, dependencies):
                return True
        return False

    dependencies = {cls: set() for cls in classes}
    for cls1 in classes:
        for cls2 in classes:
            if is_dependent(cls2, cls1, dependencies):
                dependencies[cls1].add(cls2)

    result = []
    visited = set()
    for cls in classes:
        if all(not is_dependent(cls, c, dependencies) for c in result and c != cls):
            result.append(cls)
            visited.add(cls)
    for cls in classes:
        if cls in visited:
            continue
        if all(not is_dependent(cls, c, dependencies) for c in result and c != cls):
            result.append(cls)
            visited.add(cls)

