    ''' Recursively find the difference between two dictionaries up to a specified level of depth.

    Args:
        d1 (dict): The first dictionary.
        d2 (dict): The second dictionary.
        level (int, optional): The maximum depth of recursion. Defaults to -1, meaning infinite recursion.

    Returns:
        dict: A dictionary containing the items from `d1` that are not present in `d2`.

    Raises:
        TypeError: If `d1` or `d2` is not a dictionary.
        ValueError: If `level` is less than -1.
    '''
    if not isinstance(d1, dict):
        raise TypeError("d1 must be a dictionary")
    if not isinstance(d2, dict):
        raise TypeError("d2 must be a dictionary")
    if level < -1:
        raise ValueError("level must be at least -1")

    result = {}

    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict) and level != 0:
            diff = difference(d1[key], d2[key], level - 1)
            if diff:
                result[key] = diff

    return result

