        raise TypeError("Both d1 and d2 must be dictionaries")

    result = {}

    def _difference(d1, d2, current_level):
        if current_level == 0:
            return {}

        keys = set(d1) - set(d2)
        for key in keys:
            result[key] = d1[key]

        for key in set(d1) & set(d2):
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                if level == -1 or current_level < level:
                    result[key] = _difference(d1[key], d2[key], current_level - 1)
                else:
                    result[key] = d1[key].copy()  # Force copy to prevent modifications
            elif d1[key] != d2[key]:
                result[key] = d1[key]

        return result

    return _difference(d1, d2, level)

