import re
from typing import Any, AnyStr, Dict, List, Mapping, Sequence, Tuple, Union

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    if isinstance(params, Dict):
        in_style = 'named'
    elif isinstance(params, Sequence):
        in_style = 'ordinal'
    else:
        raise TypeError("params must be a dict or a sequence")

    if in_style == 'named':
        placeholders = re.findall(r':(\w+)', sql)
        out_params = {placeholder: params[placeholder] for placeholder in placeholders}
    elif in_style == 'ordinal':
        placeholders = [f'${i+1}' for i in range(len(params))]
        out_params = [params[i] for i in range(len(params))]
        sql = sql.format(*placeholders)

    if isinstance(sql, bytes):
        out_params = {k: v if isinstance(v, bytes) else v.encode('utf-8') for k, v in out_params.items()}

    return sql, out_params

def format(
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, Mapping):
        out_style_params = {f"out_{key}": value for key, value in params.items()}
    elif isinstance(params, Sequence):
        out_style_params = [f"out_{value}" for value in params]
    else:
        raise ValueError("params must be a Mapping or Sequence")

    return sql, out_style_params

from typing import Any, AnyStr, Dict, Sequence, Tuple, Union

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if isinstance(sql, str):
            formatted_sql = sql.replace("%s", "?")
        else:
            formatted_sql = bytes(sql).replace(b"%s", b"?")

        if isinstance(params, dict):
            out_params = params.copy()
        elif isinstance(params, Sequence):
            out_params = list(params)
        else:
            raise ValueError("Invalid params type. Must be dict or Sequence.")

        return formatted_sql, out_params

    except Exception as e:
        raise ValueError(f"Failed to format SQL query: {e}")

def format(sql: Any, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[Any, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(sql, str) and isinstance(params, dict):
        # Convert in-style parameters to out-style (named parameters)
        return sql.format(**params), params
    elif isinstance(sql, bytes) and isinstance(params, Sequence):
        # Convert in-style parameters to out-style (ordinal parameters)
        placeholders = ', '.join(['?'] * len(params))
        return sql + b' ' + placeholders, params
    else:
        raise ValueError("Invalid input types for SQL or params")

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if isinstance(sql, str):
        sql_out = sql.replace('?', '%s')
    else:
        sql_out = sql.replace(b'?', b'%s')

    if isinstance(many_params, Iterable[Dict]):
        converted_params = [dict(param) for param in many_params]
    elif isinstance(many_params, Iterable[Sequence]):
        converted_params = [list(param) for param in many_params]
    else:
        raise TypeError("many_params must be an iterable of dictionaries or sequences")

    return sql_out, converted_params

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    import re

    if isinstance(sql, str):
        sql_template = re.sub(r'%(\d+|\w+)', r'{\1}', sql)
    else:
        sql_template = re.sub(br'%(\d+|\w+)', rb'{\1}', sql)

    out_params = []

    for params in many_params:
        if isinstance(params, Mapping):
            out_params.append(params)
        elif isinstance(params, Sequence):
            out_params.append(dict(zip(range(1, len(params) + 1), params)))
        else:
            raise ValueError("Invalid参数类型")

    return sql_template, out_params

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if not isinstance(many_params, (list, tuple)):
        raise ValueError("many_params must be an iterable")

    formatted_sql = sql
    converted_params: List[Union[Dict[Union[str, int], Any], List[Sequence[Any]]]] = []

    for params in many_params:
        if isinstance(params, dict):
            # Assuming out-style parameters use positional placeholders
            placeholders = tuple(f":{i}" for i in range(len(params)))
            formatted_sql = formatted_sql % placeholders
            converted_params.append([params[key] for key in sorted(params)])
        elif isinstance(params, (list, tuple)):
            # Assuming out-style parameters use positional placeholders
            placeholders = tuple(f":{i}" for i in range(len(params)))
            formatted_sql = formatted_sql % placeholders
            converted_params.append(list(params))
        else:
            raise ValueError("params must be a dictionary or a sequence")

    return formatted_sql, converted_params

