def _group_files_by_xml_filename(xml_filename, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    xml_filename : str
        XML filenames
    files : list
        list of files in the folder or zipfile

    Returns
    -------
    dict
        key: name of the XML files
        value: Package
    """
    from pathlib import Path
    from zipfile import ZipFile
    import xml.etree.ElementTree as ET

    def get_xml_root(file):
        if file.endswith('.zip'):
            with ZipFile(file) as z:
                with z.open(next(z.namelist())) as zfile:
                    tree = ET.ElementTree(ET.fromstring(zfile.read()))
        else:
            tree = ET.parse(file)
        return tree.getroot()

    def get_xml_basename(xml_filename):
        return Path(xml_filename).stem

    if not isinstance(xml_filename, str) or not isinstance(files, list):
        raise ValueError("Invalid input types. 'xml_filename' should be a string and 'files' should be a list.")

    xml_basename_dict = {}

    for file in files:
        if file.endswith('.xml'):
            try:
                root = get_xml_root(file)
                basename = get_xml_basename(xml_filename)
                if basename in xml_basename_dict:
                    xml_basename_dict[basename].append(root)
                else:
                    xml_basename_dict[basename] = [root]
            except Exception as e:
                print(f"Error processing file {file}: {e}")

    return xml_basename_dict

