def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify_expression(expr):
        if isinstance(expr, tuple):
            op, left, right = expr
            if op == '&':
                if left == right:
                    return left
                elif left == (right[0], '~', right[1]):
                    return (op, left[0], right[2])
                elif right == (left[0], '~', left[1]):
                    return (op, right[0], left[2])
            elif op == '|':
                if left == right:
                    return left
                elif left == (right[0], '~', right[1]):
                    return (op, left[0], right[2])
                elif right == (left[0], '~', left[1]):
                    return (op, right[0], left[2])
        return expr

    return [simplify_expression(expr) for expr in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            op, operands = expr
            if op == '&':
                if operands[0] == operands[1]:
                    return operands[0]
                elif operands[0] in operands[1]:
                    return operands[0]
                elif operands[1].startswith('~') and operands[1][2:] in operands[0]:
                    return (operands[1][2:],('&', operands[1][2:], operands[0]))
                elif operands[0].startswith('~') and operands[0][2:] in operands[1]:
                    return (operands[0][2:],('&', operands[0][2:], operands[1]))
            elif op == '|':
                if operands[0] == operands[1]:
                    return operands[0]
                elif operands[0] in operands[1]:
                    return operands[0]
                elif operands[1].startswith('~') and operands[1][2:] in operands[0]:
                    return (operands[1][2:],('|', operands[1][2:], operands[0]))
                elif operands[0].startswith('~') and operands[0][2:] in operands[1]:
                    return (operands[0][2:],('|', operands[0][2:], operands[1]))
        return expr

    return [apply_absorption(expr) for expr in args]

def absorb(self, args):
    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            operator, left, right = expr
            if operator == 'And':
                if isinstance(left, tuple) and left[0] == 'Or' and left[1] == left:
                    return left[2]  # Absorption
                elif isinstance(right, tuple) and right[0] == 'Or' and right[1] == left:
                    return right[2]  # Absorption
            elif operator == 'Or':
                if isinstance(left, tuple) and left[0] == 'And' and left[1] == left:
                    return left[2]  # Absorption
                elif isinstance(right, tuple) and right[0] == 'And' and right[1] == left:
                    return right[2]  # Absorption
        return expr

    def apply_negative_absorption(expr):
        def contains_negation(subtree):
            if isinstance(subtree, tuple):
                operator, *children = subtree
                if operator == 'Not':
                    return True
                return any(contains_negation(child) for child in children)
            return False

        def simplify_not(expr):
            if isinstance(expr, tuple):
                operator, *children = expr
                if operator == 'Not':
                    return simplify_and_or(children[0], not_operator=True)
                elif operator == 'And':
                    return simplify_and_or(children, not_operator=True)
                elif operator == 'Or':
                    return simplify_and_or(children, not_operator=True)
            return expr

        def simplify_and_or(subtrees, not_operator=False):
            results = [simplify_expression(subtree) for subtree in subtrees]
            if not_operator:
                results = [simplify_not(result) for result in results]
            if isinstance(results[0], tuple) and results[0][0] == 'And':
                return ('And',) + tuple(simplify_and_or(results[0][1:], not_operator) for _ in results)
            elif isinstance(results[0], tuple) and results[0][0] == 'Or':
                return ('Or',) + tuple(simplify_and_or(results[0][1:], not_operator) for _ in results)
            return tuple(results)

        if isinstance(expr, tuple) and len(expr) == 3:
            operator, left, right = expr
            if operator == 'And':
                modified_left = simplify_and_or((left,), not_operator=True)
                modified_right = simplify_and_or((right,), not_operator=True)
                if (contains_negation(left) and modified_left == right) or (contains_negation(right) and modified_right == left):
                    return apply_negative_absorption((operator, modified_left, modified_right))
            elif operator == 'Or':
                modified_left = simplify_and_or((left,), not_operator=True)
                modified_right = simplify_and_or((right,), not_operator=True)
                if (contains_negation(left) and modified_left == right) or (contains_negation(right) and modified_right == left):
                    return apply_negative_absorption((operator, modified_left, modified_right))
        return expr

    def simplify_expression(expr):
        expr = apply_absorption(expr)
        expr = apply_negative_absorption(expr)
        return expr

    return [simplify_expression(arg) for arg in args]

def absorb(self, args):
    def apply_absorption(expr1, expr2, op):
        if op == '&':
            if expr1 == expr2:
                return expr1
            elif expr1 == '!expr2':
                return expr2
            elif expr2 == '!expr1':
                return expr1
        elif op == '|':
            if expr1 == expr2:
                return expr1
            elif expr1 == '!expr2':
                return '!expr2'
            elif expr2 == '!expr1':
                return '!expr1'
        return None

    result = []
    for arg in args:
        if isinstance(arg, tuple):
            expr1, op, expr2 = arg
            new_expr = apply_absorption(expr1, expr2, op)
            if new_expr:
                result.append(new_expr)
            else:
                result.append(arg)
        else:
            result.append(arg)
    return result

