def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """

    size_map = {'k': 1000, 'm': 1000000, 'g': 1000000000, 't': 1000000000000}
    if size[-1].lower() in size_map:
        return int(float(size[:-1]) * size_map[size[-1].lower()])
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    size = size.strip().upper()
    if size.isdigit():
        return int(size)
    unit = size[-1]
    value = int(size[:-1])
    if unit == 'K':
        return value * 1000
    elif unit == 'M':
        return value * 1000 * 1000
    elif unit == 'G':
        return value * 1000 * 1000 * 1000
    else:
        raise ValueError(f"Invalid unit: {unit}")

def size_to_bytes(size: str) -> int:
    byte_scale = {
        'K': 1000,
        'M': 1000000,
        'G': 1000000000,
        'T': 1000000000000,
        'P': 1000000000000000,
        'E': 1000000000000000000,
        'Z': 1000000000000000000000,
        'Y': 1000000000000000000000000,
    }
    if not size[-1].isalpha():
        return int(size)
    unit = size[-1].upper()
    value = float(size[:-1])
    if unit in byte_scale:
        return int(value * byte_scale[unit])
    else:
        raise ValueError(f"Invalid unit: {unit}")

def size_to_bytes(size: str) -> int:
    size = size.upper()
    if size.endswith('B'):
        return int(size[:-1])
    elif size.endswith('K'):
        return int(float(size[:-1]) * 1000)
    elif size.endswith('M'):
        return int(float(size[:-1]) * 1024 * 1000)
    elif size.endswith('G'):
        return int(float(size[:-1]) * 1024 * 1024 * 1000)
    else:
        raise ValueError("Invalid size format")

def size_to_bytes(size: str) -> int:
