def vertex3tuple(vertices):
    if not all(isinstance(v, tuple) and len(v) == 2 for v in vertices):
        raise ValueError("All vertices must be tuples of 2 coordinates.")
    if len(vertices) < 4:
        raise ValueError("At least 4 vertices are required to form a polygon.")

    result = []
    n = len(vertices)
    for i in range(n):
        v1, v2, v3 = vertices[i], vertices[(i + 1) % n], vertices[(i + 2) % n]
        result.extend([(v1, v2, v3), (v2, v3, v4) for v1, v2, v3, v4 in [(v1, v2, v3, v3), (v2, v3, v4, v4)]])

    return result[:n]

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must contain only strings")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("Padding must be an integer or None")

    if number == 0:
        return alphabet[0]

    digits = []
    while number > 0:
        digits.append(number % len(alphabet))
        number //= len(alphabet)

    if padding is not None and padding > len(digits):
        digits.extend([0] * (padding - len(digits)))

    result = ''.join(alphabet[digit] for digit in digits)

    # Reverse the result to get the most significant digit first
    result = result[::-1]

    return result

from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")

    if number < 0:
        raise ValueError("Number cannot be negative")

    alphabet_length = len(alphabet)
    if padding is not None and padding < 0:
        raise ValueError("Padding cannot be negative")

    result = []
    negative = number < 0
    if negative:
        number = -number

    while number > 0:
        result.append(alphabet[number % alphabet_length])
        number //= alphabet_length

    if negative:
        result.append('-')

    if padding is not None:
        result += [alphabet[0]] * (padding - len(result))

    return ''.join(result[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet must not be empty")
    if number < 0 or number >= len(alphabet):
        raise ValueError("Number out of range for the given alphabet")

    result = []
    while number > 0:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding:
        result = [alphabet[0]] * (padding - len(result)) + result

    return ''.join(reversed(result))

