def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if padding is not None and number >= 2**padding:
        raise ValueError("Number too large for the given padding")
    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)
    if padding is not None:
        result = result.zfill(padding)
    return result

from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet must not be empty")

    if number < 0:
        raise ValueError("Number must be non-negative")

    digits = []
    base = len(alphabet)

    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    if padding is not None and padding > 0:
        digits += [alphabet[0]] * (padding - len(digits))

    return ''.join(reversed(digits)) if digits else alphabet[0]

