from typing import List

def string_to_int(string: str, alphabet: List[str]) -> int:
    digit_map = {char: index for index, char in enumerate(alphabet)}
    result = 0
    base = len(alphabet)

    for char in string:
        if char in digit_map:
            result = result * base + digit_map[char]
        else:
            raise ValueError(f"Character '{char}' not found in alphabet")

    return result

from typing import List

def string_to_int(string: str, alphabet: List[str]) -> int:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if not all(char in alphabet for char in string):
        raise ValueError("String contains characters not in the alphabet")

    base = len(alphabet)
    result = 0

    for char in string:
        index = alphabet.index(char)
        result = result * base + index

    return result

from typing import List

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string or not alphabet:
        raise ValueError("Input string and alphabet cannot be empty")

    try:
        result = 0
        base = len(alphabet)

        for char in string:
            if char not in alphabet:
                raise ValueError(f"Character {char} not found in alphabet")

            result = result * base + alphabet.index(char)

        return result

    except Exception as e:
        raise RuntimeError(f"Error converting string to int: {e}")

