import re
import platform

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = 0 if platform.startswith('win') else 1

    if platform == 1:
        return re.split(r'[ \t]', s, flags=re.UNICODE)
    elif platform == 0:
        return re.split(r'[ \t]', s, flags=re.UNICODE)
    else:
        raise ValueError("Invalid platform value. Use 'this', 0 for Windows/CMD, or 1 for POSIX.")

import subprocess
from pathlib import Path
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[Path, str] = Path("/tmp")
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not Path(archive_path).exists():
        raise FileNotFoundError(f"The archive path {archive_path} does not exist.")

    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    if not tmp_path.exists():
        raise FileNotFoundError(f"The temporary path {tmp_path} does not exist.")
    elif not tmp_path.is_dir():
        raise NotADirectoryError(f"The temporary path {tmp_path} is not a directory.")

    if filename is None:
        filename = Path(archive_path).name

    extracted_path = tmp_path / filename
    if extracted_path.exists():
        subprocess.run(["rm", "-rf", extracted_path], check=True)

    subprocess.run(["unzip", archive_path, "-d", extracted_path], check=True)

    return str(extracted_path)

import subprocess
from typing import Optional, Union
from pathlib import PosixPath

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if filename is None:
        filename = archive_path.split('/')[-1]
    if isinstance(tmp_path, str):
        tmp_path = PosixPath(tmp_path)

    temp_dir = tmp_path / filename.replace('.tar.gz', '').replace('.zip', '')
    temp_dir.mkdir(exist_ok=True, parents=True)

    try:
        if archive_path.endswith('.tar.gz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', temp_dir], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', temp_dir], check=True)
        else:
            raise ValueError("Unsupported archive format")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}")

    repo_url = f"file://{temp_dir}"
    return repo_url

