def addignored(ignored):
    try:
        result = subprocess.run(['git', 'ls-files', '--ignored'], capture_output=True, text=True, check=True)
        ignored_files = [line.strip() for line in result.stdout.splitlines() if line.strip() in ignored]
        return ','.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        return f"Error: {e.stderr}"

def addignored(ignored):
    try:
        result = subprocess.run(['git', 'status', '--ignored', '--porcelain'], capture_output=True, text=True, check=True)
        files = [line.split()[1] for line in result.stdout.split('\n') if line]
        ignored_files = [file for file in files if any(file.startswith(prefix) for prefix in ignored)]
        return ','.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        return f"Error: {e.stderr.strip()}"

import subprocess

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        result = subprocess.run(['git', 'ls-files', '--others', '--exclude-standard'], capture_output=True, text=True, check=True)
        files = result.stdout.strip().split('\n')
        ignored_files = [file for file in files if file in ignored]
        ignored_files.sort()
        return ','.join(ignored_files)
    except subprocess.CalledProcessError as e:
        return f"Error executing git command: {e}"
    except Exception as e:
        return f"An unexpected error occurred: {e}"

import datetime

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        number, unit = frequency.split()
        number = int(number)
        if unit.endswith('s'):
            unit = unit[:-1]
        if unit == 'second':
            return datetime.timedelta(seconds=number)
        elif unit == 'minute':
            return datetime.timedelta(minutes=number)
        elif unit == 'hour':
            return datetime.timedelta(hours=number)
        elif unit == 'day':
            return datetime.timedelta(days=number)
        elif unit == 'week':
            return datetime.timedelta(weeks=number)
        elif unit == 'month':
            return datetime.timedelta(days=number * 30)
        elif unit == 'year':
            return datetime.timedelta(days=number * 365)
        else:
            raise ValueError("Unsupported time unit: {}".format(unit))
    except (ValueError, AttributeError):
        raise ValueError("Invalid frequency format: {}".format(frequency))

