def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    import re
    match = re.match(r'(\d+)\s*(weeks?|days?|hours?|minutes?|seconds?)$', frequency, re.IGNORECASE)
    if not match:
        raise ValueError("Invalid frequency format")
    num, unit = match.groups()
    return {
        'weeks': lambda: datetime.timedelta(weeks=int(num)),
        'days': lambda: datetime.timedelta(days=int(num)),
        'hours': lambda: datetime.timedelta(hours=int(num)),
        'minutes': lambda: datetime.timedelta(minutes=int(num)),
        'seconds': lambda: datetime.timedelta(seconds=int(num)),
    }.get(unit.lower(), lambda: None)()

