def make_find_paths(find_paths):
    if not all(isinstance(path, str) for path in find_paths):
        raise ValueError("All elements in find_paths must be strings")

    glob_pattern = 'sh:**/*{path}/**'
    transformed_paths = []

    for path in find_paths:
        if re.match(r'\w+:', path):
            transformed_paths.append(path)
        else:
            transformed_paths.append(glob_pattern.format(path=path))

    return transformed_paths

