import subprocess
from typing import Any, Dict, Sequence

def subprocess_run_helper(func: Any, *args: str, timeout: int, extra_env: Dict[str, str] = None) -> subprocess.CompletedProcess:
    try:
        if extra_env:
            env = {**os.environ, **extra_env}
        else:
            env = os.environ

        result = subprocess.run([func, *args], timeout=timeout, env=env, check=True)
        return result
    except subprocess.CalledProcessError as e:
        print(f"Subprocess returned non-zero exit status: {e.returncode}")
        raise e
    except subprocess.TimeoutExpired as e:
        print("Subprocess timed out")
        raise e
    except Exception as e:
        print(f"An error occurred: {e}")
        raise e

import os

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    name, default = matcher.split('=' if '=' in matcher else '')
    value = os.getenv(name.strip())
    if value is None:
        if default:
            return default.strip()
        else:
            raise ValueError(f"Environment variable '{name}' is not set and no default value provided.")
    return value

