from rdflib import Graph, URIRef, Node

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    children = set(child for child, predicate, parent in graph.triples((None, prop, None)))
    parents = set(parent for child, predicate, parent in graph.triples((None, prop, None)))

    if not children:
        return roots

    new_roots = parents - children
    roots.update(new_roots)

    return find_roots(graph, prop, roots)

