class Time:
    @classmethod
    def from_ticks(cls, ticks, tz=None):
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")
        total_seconds = ticks / 1e9
        naive_time = datetime.time.fromtimestamp(total_seconds)
        if tz is not None:
            naive_time = datetime.datetime.combine(datetime.date.today(), naive_time).replace(tzinfo=tz).time()
        return cls(naive_time)

