    # Create the graph
    graph = graph_class(len(bin_centers))

    for i, (x, y) in enumerate(zip(bin_centers, bin_contents)):
        if get_coordinate == "left":
            graph.SetPoint(i, bin_edges[i], y)
        elif get_coordinate == "right":
            graph.SetPoint(i, bin_edges[i + 1], y)
        elif get_coordinate == "middle":
