    implemented_interfaces = iface.directlyProvidedBy(candidate_class)

    if not implemented_interfaces and not candidate_class.providedBy(candidate):
        raise zope.interface.Invalid(f"Candidate's class does not implement the interface {iface}")

    candidates_methods = set(dir(candidate))
    required_methods = set(iface.names())

    missing_methods = required_methods - candidates_methods
