        error_message = f"Candidate is missing the following required methods: {', '.join(missing_methods)}"
        if len(missing_methods) == 1:
            raise zope.interface.Invalid(error_message)
        raise zope.interface.Invalid(f"Multiple errors: {error_message}")

    for method_name in required_methods:
        candidate_method = getattr(candidate, method_name)
        if not callable(candidate_method):
            raise zope.interface.Invalid(f"Method {method_name} is not callable in the candidate")

    candidates_attributes = set(dir(candidate))
    required_attributes = set(iface.attributes().keys())

    missing_attributes = required_attributes - candidates_attributes
    if missing_attributes:
        error_message = f"Candidate is missing the following required attributes: {', '.join(missing_attributes)}"
        if len(missing_attributes) == 1:
            raise zope.interface.Invalid(error_message)
        raise zope.interface.Invalid(f"Multiple errors: {error_message}")

    return True

