    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"{candidate} does not claim to provide {iface}")

    candidate_interface = zope.interface.implementedBy(candidate)
    candidate_methods = set(dir(candidate)) - {'__dict__', '__weakref__', '__module__'}
    required_methods = set(dir(iface)) - {'__dict__', '__weakref__', '__module__'}
    required_attributes = set()
    for method_name in required_methods:
        method = getattr(iface, method_name)
        if isinstance(method, zope.interface.Method):
            required_attributes.update(method.interface.impliedAttributes)

    missing_methods = required_methods - candidate_methods
    if missing_methods:
        raise Invalid(f"{candidate} lacks methods: {', '.join(missing_methods)}")

    missing_attributes = required_attributes - candidate_methods
    if missing_attributes:
        raise Invalid(f"{candidate} lacks attributes: {', '.join(missing_attributes)}")

    for method_name in candidate_methods:
        expected = getattr(iface, method_name, None)
        if isinstance(expected, zope.interface.Method):
            got = getattr(candidate, method_name)
            if not ismethod(got):
                raise Invalid(f"{candidate} does not define {method_name} as a method")
            sig_got = signature(got)
            sig_expected = signature(expected)
            if sig_got != sig_expected:
                raise Invalid(f"{method_name} signature mismatch: expected {sig_expected}, got {sig_got}")

    return True

