def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re

    def replacer_func(match):
        tag = match.group(1)
        if replacer:
            return replacer(tag)
        return tag

    tags = set()
    code_block_pattern = re.compile(r'(```[\s\S]*?```|`[^`]*`)', re.DOTALL)
    text_parts = code_block_pattern.split(text)

    for part in text_parts:
        if part.startswith('```'):
            # This is a code block, ignore tags inside it
            part = re.sub(r'<([^>]+)>', '', part)
        else:
            # Extract tags from plain text
            part_tags = re.findall(r'<([^>]+)>', part)
            tags.update(part_tags)
            if replacer:
                part = re.sub(r'<([^>]+)>', replacer_func, part)

    return tags, ''.join(text_parts)

