from collections import defaultdict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"Plugin directory {plugin_dir} not found")

    spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"Plugin spec file not found in {plugin_dir}")

    with open(spec_path, 'r') as file:
        spec_data = json.load(file)

    def is_json_serializable(obj):
        try:
            json.dumps(obj)
            return True
        except (TypeError, OverflowError):
            return False

    def flatten_dict(d, parent_key='', sep='__'):
        items = defaultdict(list)
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten_dict(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    if is_json_serializable(item):
                        items[f"{new_key}_{i}"].append(item)
            else:
                if is_json_serializable(v):
                    items[new_key].append(v)
        return dict(items)

    return flatten_dict(spec_data)

